__NUXT_JSONP__("/finanzas-publicas/noticias/precio_de_la_mezcla_mexicana_de_petroleo_podria_llegar_a_90_dolares_estiman_analistas_guerra_deja_incertidumbre", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n){return {data:[{post:{slug:"precio_de_la_mezcla_mexicana_de_petroleo_podria_llegar_a_90_dolares_estiman_analistas_guerra_deja_incertidumbre",title:"Precio de la mezcla mexicana de petróleo podría llegar a 90 dólares, estiman analistas; guerra deja incertidumbre",date:"2026-03-10T19:27:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F13c961c8-18e1-470e-b62e-62587b839758\u002F","img-alt":"Liliana Alvarado",autor:"Leonor Flores y Everardo Martínez, El Universal",link:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Fprecio-de-la-mezcla-mexicana-de-petroleo-podria-llegar-a-90-dolares-estiman-analistas-guerra-deja-incertidumbre\u002F",category:"finanzas-publicas",extracto:"Liliana Alvarado, comentó que la guerra entre EU-Israel contra Irán ha provocado el aumento de los petroprecios en los mercados energéticos internacionales.   Para el caso de México, se presupuestó para este año en 54.90 dólares por barril, pero hoy nos amanecimos con cotizaciones mundiales de 119 dólares.",toc:[{id:j,depth:2,text:k}],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Con la escalada de los"},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fmundo\u002Feu-lanza-otro-ataque-contra-supuesta-narcolancha-en-el-pacifico-seis-hombres-mueren-en-el-operativo\u002F?outputType=amp\u002F",rel:[f,g,h],target:i},children:[{type:a,value:" ataques"}]},{type:a,value:" contra Irán, es probable que el precio de la mezcla mexicana del petróleo cierre la jornada de este lunes en 90 dólares; sin embargo, mientras persista el constante apoyo a Petróleos Mexicanos (Pemex) y los subsidios a gasolinas, no servirán de mucho para cumplir la meta del "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Fpara-baja-deficit-fiscal-sacrifican-bienestar\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"déficit fiscal "}]},{type:a,value:"en 2026, alertaron especialistas."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Para México, primero, sin duda el choque petrolero es la parte más relevante; la mezcla mexicana al cierre del viernes cotizaba alrededor de 82 dólares por barril, con estas referencias cercanas a los 100 dólares del Brent y WTI. Lo más probable es que hoy, al cierre de la jornada, veremos una mezcla más cerca de los 90 dólares”, estimó el economista en jefe de la casa de bolsa Finamex, Víctor Gómez Ayala."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Durante la presentación del análisis “Navegando las Finanzas Públicas de 2025”, elaborado por la organización México Evalúa, explicó el efecto inicial del crecimiento de los "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fmundo\u002Fprecio-del-petroleo-y-gas-se-disparan-en-todo-el-mundo-por-conflicto-entre-eu-israel-e-iran-tension-hace-caer-la-bolsa\u002F?outputType=amp\u002F",rel:[f,g,h],target:i},children:[{type:a,value:l}]},{type:a,value:" por la intervención militar en Irán y el ataque a diferentes estructuras de almacenamiento en Irán."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Indicó que en la apertura de los mercados en Asia, se observó un aumento importante en los "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fnacion\u002Fsheinbaum-descarta-alza-en-precio-del-gas-pese-a-conflicto-internacional-se-mantienen-acciones-con-sener-y-cfe\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"precios internacionales"}]},{type:a,value:" del crudo, tanto del Brent como del WTI."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Como es un elemento de riesgo, no solo se canaliza en el mercado de commodities, sino también en otros, en el cambiario y de metales, así como en los"},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Ffed-advierte-a-bancos-de-riesgos-relacionados-con-los-criptoactivos-exige-cautela-en-su-manejo\u002F",rel:[f,g,h],target:i},children:[{type:a,value:" criptoactivos"}]},{type:a,value:", señaló."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Estableció que el efecto sobre las finanzas públicas dependerá del tamaño del estímulo fiscal que pudiera reactivar el gobierno federal para las "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Fpublica-shcp-ajustes-en-ieps-para-gasolinas-cigarros-y-refrescos-a-partir-de-2026\u002F",rel:[f,g,h],target:i},children:[{type:a,value:m}]},{type:a,value:" y la duración del conflicto, que al parecer ya se le está saliendo de las manos a Estados Unidos porque claramente "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fmundo\u002Festados-unidos-levanta-sanciones-para-la-explotacion-del-oro-en-venezuela-ocurre-tras-reunion-con-delcy-rodriguez\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Venezuela"}]},{type:a,value:" no es Irán."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Al respecto, la directora general del laboratorio de políticas públicas Ethos, Liliana Alvarado, comentó que la guerra entre EU-Israel contra Irán ha provocado el aumento de los petroprecios en los mercados energéticos internacionales."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Para el caso de México, se presupuestó para este año en 54.90 "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Fcierre-del-estrecho-de-ormuz-podria-disparar-petroleo-a-150-dolares-mexico-con-impactos-fiscales\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"dólares"}]},{type:a,value:" por barril, pero hoy nos amanecimos con cotizaciones mundiales de 119 dólares."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Eso significa una pérdida de recursos para el gobierno mexicano porque recordemos que tenemos el subsidio a las gasolinas”, manifestó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En 2022, la pérdida recaudatoria fue de 1.14% del "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Fanalistas-mejoran-prevision-del-pib-de-mexico-para-2026-economia-creceria-15-segun-encuesta-de-citi\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"producto interno bruto"}]},{type:a,value:" (PIB), es importante en términos de recaudación, ponderó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Por su parte, la directora general de México Evalúa, Mariana Campos, dijo que no hay que olvidar que el año pasado se hizo una reforma para crear el nuevo Derecho Petrolero del Bienestar, del 30%, con lo cual el gobierno ya no recibe ingresos por el pago de impuestos de "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fopinion\u002Fmario-maldonado\u002Fla-fiesta-del-contratista-de-pemex-y-los-nuevos-ricos-de-tabasco\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Pemex"}]},{type:a,value:n}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Con ello, ahora es más difícil que los altos "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fmundo\u002Ftrump-minimiza-alza-del-petroleo-por-guerra-con-iran-afirma-que-es-un-pequeno-precio-a-pagar\u002F",rel:[f,g,h],target:i},children:[{type:a,value:l}]},{type:a,value:" vayan a beneficiar el presupuesto federal, porque de entrada el gobierno ya recibe menos por la venta de crudo, afirmó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Recordó que en 2022 estimaron una pérdida de 128 mil millones de pesos menos el costo de los estímulos para mantener los precios de las "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Fgasolina-mas-cara-que-nunca-por-cobro-total-de-impuestos\u002F",rel:[f,g,h],target:i},children:[{type:a,value:m}]},{type:a,value:", con un resultado más caro que el efecto favorable."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Además, hizo ver que también existe un estímulo fiscal para los gasolineros que apoyen mantener el precio de los combustibles por debajo de la inflación, cuando se agota el subsidio directo a los consumidores."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Posiblemente, para el sector público pudiera ser positivo, pero para el financiamiento del presupuesto de egresos de la Federación no lo fue en 2022; vamos a ver qué pasa ahora”, puntualizó."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Es decir, que esos recursos se quedan en la empresa petrolera y no en el gobierno federal que necesita financiar su déficit, por lo que comentó que es parte de la nueva era de las "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fopinion\u002Fjavier-guzman-calafell\u002Flos-desafios-para-las-finanzas-publicas\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"finanzas públicas "}]},{type:a,value:"“despetrolizadas”, por lo que es importante atender elementos que estén a la mano porque el contexto externo no se puede controlar para no perder el grado de inversión de las calificadoras."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Dentro de ese contexto, el coordinador del programa de Gasto Público de México Evalúa, Jorge Cano, hizo ver que de nada servirán mayores ingresos petroleros frente a los apoyos que recibe"},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Festados\u002Fsorprende-millonario-con-fiesta-de-xv-anos-es-contratista-de-pemex\u002F",rel:[f,g,h],target:i},children:[{type:a,value:" Pemex"}]},{type:a,value:n}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Lo anterior porque ya dejó de aportar a las finanzas públicas, pues la renta petrolera neta en 2025 fue de 240 mil millones de pesos, pero el gobierno federal le inyectó más de 3 mil millones de pesos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Así el estado terminó con una pérdida neta de 156 mil millones de pesos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En términos per cápita, afirmó que los ciudadanos, en lugar de recibir una aportación neta de Pemex, tuvieron que subsidiar a la empresa petrolera con mil 173 pesos por persona, frente a 2008, cuando Pemex aportaba 16 mil 423 pesos por persona."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De ahí que para Liliana Alvado, será muy difícil que para el 2026 se cumpla con la meta establecida para el déficit fiscal para continuar con el proceso de consolidación prometido."}]},{type:a,value:d},{type:b,tag:"h2",props:{id:j},children:[{type:b,tag:e,props:{href:"#revierte-est%C3%ADmulo-a-gasolinas-la-ganancia-del-crudo-caro-por-la-guerra-imco",ariaHidden:"true",tabIndex:-1},children:[{type:b,tag:"span",props:{className:["icon","icon-link"]},children:[]}]},{type:a,value:k}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El impulso que la guerra en medio oriente le da al precio del petróleo y por ende a los ingresos del gobierno por la venta al extranjero puede desvanecerse totalmente por los estímulos fiscales que mantendrían estables los valores de las gasolinas en las estaciones de servicios, explicó el "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.eluniversal.com.mx\u002Fcartera\u002Fante-aranceles-globales-de-trump-productos-de-mexico-mantienen-ventaja-imco-que-gravamenes-impactan-al-pais-esto-dice\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Instituo Mexicano para la Competitividad "}]},{type:a,value:"(Imco)."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Si el precio promedio del petróleo cierra el año en 90 dólares por barril los ingresos petroleros adicionales alcanzarían aproximadamente 406 mil millones de pesos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“No obstante, este beneficio podría revertirse si el gobierno federal reactiva estímulos al (Impuesto Especial a Producción y Servicios) IEPS para contener la inflación en el precio de las gasolinas, como ocurrió en 2022”, señaló el Imco en un nuevo informe."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El Imco recordó que esta situación ya ha sucedido, por ejemplo en 2022. Añadió que el beneficio se reduce si el gobierno activa estímulos al IEPS para contener el precio de las gasolinas."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En 2022, el costo de los estímulos alcanzó 395.4 mil millones de pesos y prácticamente anuló los ingresos petroleros adicionales que fueron 394.5 mil millones de pesos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Y es que como México extrae petróleo y lo vende, y hoy el crudo es más caro, lo que incrementa sus ingresos."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De acuerdo con el Paquete Económico 2026, cada dólar adicional en el precio del petróleo genera cerca de 11.6 mil millones de pesos extra en ingresos petroleros."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"No obstante, cabe destacar que en 2025, las exportaciones de crudo bajaron 50% debido a que la producción se estaba concentrando en el abastecimiento de las refinerías en México."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Sin embargo, este hecho tiene otro efecto positivo que es reducir la importación de gasolinas del extranjero y reducir el efecto negativo de estar expuesto al mercado internacional."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Por ahora, el petróleo ya está por encima de lo previsto en el Paquete Económico 2026. De un estimado de 54.9 dólares por barril, hoy el precio supera los 80 dólares por barril."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Cabe recordar que el 28 de febrero inició el conflicto entre EU, Israel e Irán. Al 8 de marzo, el crudo WTI subió 60% y el Brent 49%, ambos por encima de 100 dólares por barril y la mezcla mexicana de exportación aumentó 30%. Los precios alcanzaron su nivel más alto desde enero de 2025."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fprecio_de_la_mezcla_mexicana_de_petroleo_podria_llegar_a_90_dolares_estiman_analistas_guerra_deja_incertidumbre",extension:".md",createdAt:"2026-07-19T00:56:17.246Z",updatedAt:"2026-07-19T00:56:17.250Z"}}],fetch:{},mutations:[]}}("text","element","p","\n","a","nofollow","noopener","noreferrer","_blank","revierte-estímulo-a-gasolinas-la-ganancia-del-crudo-caro-por-la-guerra-imco","Revierte estímulo a gasolinas la ganancia del crudo caro por la guerra: Imco","precios del petróleo","gasolinas",".")));